from seed_data import _id, _intro, _teach, _example, _flash, _mcq, _concept
from seed_finance import _choice, _outcome

CFA_SEED_VERSION = "cfa-1"

DISCLAIMER = ("Independent study material for learners preparing for finance exams. Not affiliated with or endorsed by "
              "CFA Institute. CFA and Chartered Financial Analyst are trademarks owned by CFA Institute. "
              "Educational only, not investment advice.")


def _quant_chapter(course_id):
    ch_id = _id()
    ch = {
        "id": ch_id, "course_id": course_id, "order": 1,
        "title": "Quantitative Methods",
        "description": "Time value of money, returns, descriptive statistics and the normal distribution, the maths behind every valuation.",
    }
    m_id = _id()
    m = {"id": m_id, "chapter_id": ch_id, "order": 1, "title": "Core quantitative tools"}

    c1 = _concept(m_id, 1,
        "Time value of money",
        "Calculate future value, present value, effective annual rate and annuity values.",
        "A rupee today is worth more than a rupee later, because today's rupee can earn a return. "
        "Time value of money gives you the tools to move cash flows across time using an interest or discount rate.",
        "A scholarship fund invests ₹2,00,000 at 8% a year for 5 years and grows to about ₹2,93,866.",
        ["FV = PV × (1 + r)^n and PV = FV ÷ (1 + r)^n.",
         "More frequent compounding gives a higher effective annual rate (EAR).",
         "An ordinary annuity pays at the end of each period.",
         "Rule of 72: years to double ≈ 72 ÷ interest rate (in %)."],
        ["Comparing stated rates with different compounding frequencies.",
         "Using years for n but a monthly rate for r (mismatched periods).",
         "Forgetting that an annuity due pays at the start of each period."],
        [
            _intro("Why waiting costs money",
                   "You are offered ₹1,00,000 today or ₹1,05,000 a year from now. Which one is better? The answer depends on a single number: the return you could earn while you wait."),
            _teach("Future value and present value",
                   "Future value (FV) is what money grows to. If you invest PV at rate r for n periods with annual compounding, FV = PV × (1 + r)^n. Present value does the reverse: PV = FV ÷ (1 + r)^n. Here r is the interest rate per period and n is the number of periods, and both must use the same time unit. If you have monthly periods, use a monthly rate and the number of months.",
                   ["FV = PV × (1 + r)^n", "PV = FV ÷ (1 + r)^n", "Match the rate period to the number of periods"]),
            _example("The scholarship fund",
                     "A college fund invests ₹2,00,000 at 8% per year, compounded annually, for 5 years. Growth factor: 1.08^5 = 1.469328. FV = 2,00,000 × 1.469328 = ₹2,93,866 (rounded). In other words the fund earns about ₹93,866 of interest, mostly because later years earn interest on earlier interest.",
                     "Compounding means you earn interest on interest, so growth accelerates."),
            _flash("Formula for present value?", "PV = FV ÷ (1 + r)^n"),
            _choice("Two banks both advertise a 12% stated annual rate on a ₹1,00,000 deposit. Bank A compounds once a year. Bank B compounds monthly (1% a month).",
                    "Which deposit gives the higher effective annual return?",
                    [("Bank A and Bank B are the same, because both state 12%", "bad",
                      "A stated rate only tells you the rate before compounding. Bank B compounds twelve times a year, so interest starts earning interest sooner.",
                      _outcome(("Bank A after one year", 112000), ("Bank B after one year", 112683), "Effective annual rates: Bank A is 12.00%, Bank B is (1.01)^12 − 1 = 12.68%.")),
                     ("Bank B, because monthly compounding gives an effective rate of about 12.68%", "good",
                      "Correct. EAR = (1 + r/m)^m − 1. With r = 12% and m = 12, EAR = (1.01)^12 − 1 ≈ 12.68%. Always convert to EAR before comparing deposits that compound differently.",
                      _outcome(("Bank A after one year", 112000), ("Bank B after one year", 112683), "Same stated rate, but monthly compounding earns ₹683 more on ₹1,00,000.")),
                     ("Bank A, because annual compounding is simpler and safer", "bad",
                      "Simplicity does not change the maths. For the same stated rate, more frequent compounding always yields at least as much.")]),
            _teach("Annuities and the rule of 72",
                   "An ordinary annuity is a series of equal payments at the end of each period. Its present value is PV = PMT × [1 − (1 + r)^−n] ÷ r. For ₹10,000 a year for 5 years at 8%, the factor is about 3.9927, so PV ≈ ₹39,927. An annuity due pays at the start of each period, so it is worth (1 + r) times as much. For a quick estimate of doubling time, the rule of 72 says years to double ≈ 72 ÷ r (with r in percent). At 9%, money doubles in about 8 years.",
                   ["Ordinary annuity: payments at the end of each period", "Annuity due = ordinary annuity × (1 + r)", "Rule of 72: 72 ÷ rate = years to double"]),
            _choice("A lottery offers a winner either ₹1,00,000 today or ₹1,05,000 exactly one year from now. The winner can earn 6% a year on any money received today.",
                    "Which payout is worth more in today's money?",
                    [("Take ₹1,05,000 later, because it is a bigger number", "bad",
                      "A bigger number later is not automatically worth more. You must discount it to today's value before comparing.",
                      _outcome(("Cash today", 100000), ("₹1,05,000 later, valued today at 6%", 99057), "₹1,05,000 ÷ 1.06 ≈ ₹99,057, which is less than ₹1,00,000.")),
                     ("Take ₹1,00,000 today, because ₹1,05,000 ÷ 1.06 ≈ ₹99,057 is worth less today", "good",
                      "Correct. Compare values at the same point in time. The later payout is worth about ₹99,057 today, so ₹1,00,000 now is better. At a 4% rate the answer would flip, since ₹1,05,000 ÷ 1.04 ≈ ₹1,00,962.",
                      _outcome(("Cash today", 100000), ("₹1,05,000 later, valued today at 6%", 99057), "A small difference, but it flips if the discount rate changes.")),
                     ("They are equal, because both are the same money", "bad",
                      "They would be equal only if the discount rate were exactly 5%. At 6% they are not.")]),
            _mcq("What is the future value of ₹1,00,000 invested at 10% a year for 2 years, compounded annually?",
                 ["₹1,10,000", "₹1,20,000", "₹1,21,000", "₹1,10,100"], 2,
                 "FV = 1,00,000 × (1.10)^2 = 1,00,000 × 1.21 = ₹1,21,000. Simple interest would give ₹1,20,000, but compounding earns interest on the first year's interest."),
            _mcq("Using the rule of 72, about how many years does it take money to double at 9% a year?",
                 ["6 years", "8 years", "9 years", "12 years"], 1,
                 "72 ÷ 9 = 8 years. The rule is an estimate, but it works well for rates between about 6% and 10%."),
        ], xp=30)

    c2 = _concept(m_id, 2,
        "Returns: holding period, average and real",
        "Compute holding period return, arithmetic and geometric means, and real returns.",
        "A return measures your gain as a percentage of what you put in. How you average returns over several years matters: "
        "the arithmetic mean overstates growth when returns swing, while the geometric mean shows what you actually compounded at.",
        "An investor buys a share at ₹100, receives a ₹4 dividend and sells at ₹112, a holding period return of 16%.",
        ["HPR = (P1 − P0 + D) ÷ P0.",
         "Geometric mean ≤ arithmetic mean; it measures compound growth.",
         "Real return ≈ (1 + nominal) ÷ (1 + inflation) − 1.",
         "Time-weighted return judges a manager; money-weighted return reflects the investor's own timing."],
        ["Averaging returns with the arithmetic mean to describe growth.",
         "Subtracting inflation from nominal return instead of using the exact formula.",
         "Judging a manager with a money-weighted return."],
        [
            _intro("What did you actually earn?", "Your fund shows +20%, −10% and +15% over three years. Did you earn 8.3% a year, or something less? The way you average makes a real difference."),
            _teach("Holding period return and averages",
                   "Holding period return (HPR) over one period is (P1 − P0 + D) ÷ P0, where D is income received. To summarise several periods you can use the arithmetic mean (simple average) or the geometric mean, which is (Π(1 + R))^(1/n) − 1. The geometric mean captures compounding and is never higher than the arithmetic mean. The bigger the swings, the larger the gap. To annualise a monthly return of 1%, compound it: (1.01)^12 − 1 ≈ 12.68%.",
                   ["HPR = (P1 − P0 + D) ÷ P0", "Geometric mean = compound growth rate", "Annualise by compounding, not by multiplying by 12"]),
            _example("A share and its dividend",
                     "Priya buys a share for ₹100. During the year it pays a ₹4 dividend and at year end she sells it for ₹112. HPR = (112 − 100 + 4) ÷ 100 = 16 ÷ 100 = 16%. Of that, 12 percentage points came from the price rising and 4 from the dividend.",
                     "HPR includes both price change and income."),
            _flash("Which average best shows true compound growth over several years?", "The geometric mean."),
            _choice("A fund returned +20%, −10% and +15% over three years. An advertisement says the fund 'averaged 8.33% a year'.",
                    "Which statement describes what an investor who held for all three years actually earned per year?",
                    [("About 8.33% a year, the average of the three returns", "bad",
                      "8.33% is the arithmetic mean. Because returns swing, it overstates what you actually compounded at.",
                      _outcome(("₹1,00,000 growing at 8.33% for 3 years", 127141), ("What the investor actually ended with", 124200), "1.20 × 0.90 × 1.15 = 1.242, so ₹1,00,000 became ₹1,24,200.")),
                     ("About 7.49% a year, the geometric mean: (1.20 × 0.90 × 1.15)^(1/3) − 1", "good",
                      "Correct. The geometric mean gives the constant annual rate that reproduces the actual ending value. Compounding 7.49% for three years gives about ₹1,24,200.",
                      _outcome(("₹1,00,000 growing at 8.33% for 3 years", 127141), ("What the investor actually ended with", 124200), "The ad's average overstates the ending value by almost ₹3,000.")),
                     ("25% a year, the sum of the three returns", "bad",
                      "Adding returns ignores compounding and treats three years as one. The total over three years is 24.2%, not 25% a year.")]),
            _teach("Time-weighted vs money-weighted, and real returns",
                   "The time-weighted return (TWR) compounds the returns of sub-periods and ignores when money was added or withdrawn, so it is the standard way to judge a manager. The money-weighted return (MWR) is the internal rate of return of the investor's actual cash flows, so it reflects both the manager's results and the investor's timing. Finally, a real return strips out inflation: real ≈ (1 + nominal) ÷ (1 + inflation) − 1. With a 10% nominal return and 6% inflation, real is 1.10 ÷ 1.06 − 1 ≈ 3.77%.",
                   ["TWR: removes the effect of cash flow timing", "MWR (IRR): includes the investor's timing", "Real return uses division, not simple subtraction"]),
            _choice("An investor added a large amount of money just before a bad year for a fund and a good year came after. The investor's own money-weighted return is poor, but the fund's returns each year look fine.",
                    "Which measure should be used to judge the fund manager's skill?",
                    [("The time-weighted return, because it removes the effect of the investor's cash flow timing", "good",
                      "Correct. The manager does not control when clients add or withdraw money, so TWR is the fair measure of the manager's performance."),
                     ("The money-weighted return, because it uses the actual cash flows", "bad",
                      "MWR is affected by the investor's timing decisions, which the manager cannot control. It describes the investor's experience, not the manager's skill."),
                     ("The simple average of the account balances", "bad",
                      "Averaging balances ignores returns and cash flows and does not measure performance.")]),
            _mcq("A share is bought for ₹50, pays a ₹2 dividend and is sold for ₹55. What is the holding period return?",
                 ["10%", "14%", "4%", "7%"], 1,
                 "HPR = (55 − 50 + 2) ÷ 50 = 7 ÷ 50 = 14%."),
            _mcq("The nominal return is 10% and inflation is 6%. What is the exact real return?",
                 ["4.00%", "3.77%", "16.60%", "6.00%"], 1,
                 "Real return = 1.10 ÷ 1.06 − 1 ≈ 3.77%. The quick subtraction (10% − 6% = 4%) is only an approximation."),
        ], xp=30)

    c3 = _concept(m_id, 3,
        "Describing data: centre, spread and Sharpe ratio",
        "Choose between mean and median, compute variance and standard deviation, and use the Sharpe ratio.",
        "Statistics summarise a pile of numbers with a few. The mean and median say where the middle is, "
        "the standard deviation says how spread out the data is, and the Sharpe ratio asks how much extra return you earned per unit of risk.",
        "Five analysts get bonuses of ₹2,00,000, ₹2,20,000, ₹2,50,000, ₹2,80,000 and ₹20,00,000. The mean is ₹5.9 lakh but the median is ₹2.5 lakh.",
        ["Median resists outliers; the mean does not.",
         "Sample variance divides by n − 1; population variance divides by n.",
         "Coefficient of variation = standard deviation ÷ mean.",
         "Sharpe ratio = (Rp − Rf) ÷ σp."],
        ["Using the mean for skewed data.",
         "Dividing by n instead of n − 1 for a sample.",
         "Choosing the fund with the higher return without adjusting for risk."],
        [
            _intro("Which number tells the truth?", "A company says its average bonus is ₹5.9 lakh. Most staff got less than half of that. Both statements are true, which is why choosing the right statistic matters."),
            _teach("Centre and spread",
                   "The mean is the sum divided by the count. The median is the middle value when sorted, and the mode is the most frequent value. In a positively skewed distribution a few very large values pull the mean above the median. Spread is measured by variance and standard deviation. For a sample, sample variance = Σ(x − mean)² ÷ (n − 1), and the standard deviation is its square root. The n − 1 corrects for the fact that a sample tends to understate the spread of the population. The coefficient of variation, standard deviation ÷ mean, compares spread across data sets with different averages.",
                   ["Skewed data: prefer the median", "Sample variance divides by n − 1", "CV = SD ÷ mean, for comparing relative risk"]),
            _example("Five monthly returns",
                     "A fund returned 4%, 6%, 8%, 10% and 12% in five months. Mean = 40 ÷ 5 = 8%. Squared deviations: 16, 4, 0, 4, 16, total 40. Sample variance = 40 ÷ 4 = 10, so sample standard deviation ≈ 3.16%. If these five months were the whole population, variance would be 40 ÷ 5 = 8 and standard deviation about 2.83%.",
                     "Sample statistics divide by n − 1, population statistics by n."),
            _flash("Sample variance divides the sum of squared deviations by what?", "n − 1 (the number of observations minus one)."),
            _choice("A company lists five analyst bonuses: ₹2,00,000, ₹2,20,000, ₹2,50,000, ₹2,80,000 and ₹20,00,000. A new hire asks what a typical bonus looks like.",
                    "Which statistic best describes a typical bonus?",
                    [("The mean, ₹5.9 lakh", "bad",
                      "The single ₹20 lakh bonus pulls the mean far above what four of the five analysts received. The mean is distorted by outliers.",
                      _outcome(("Mean bonus", 590000), ("Median bonus", 250000), "The median is ₹2.5 lakh, much closer to what most analysts got.")),
                     ("The median, ₹2.5 lakh", "good",
                      "Correct. With a strong outlier, the median is the better measure of the typical value because it is not pulled by extreme values.",
                      _outcome(("Mean bonus", 590000), ("Median bonus", 250000), "Four of five analysts earned between ₹2 lakh and ₹2.8 lakh.")),
                     ("The highest bonus, ₹20 lakh, because that shows what is possible", "bad",
                      "The maximum is not a measure of the centre of the data and describes only one person.")]),
            _teach("Risk-adjusted return: the Sharpe ratio",
                   "A higher return is not better if it came with much more risk. The Sharpe ratio measures excess return per unit of total risk: Sharpe = (Rp − Rf) ÷ σp, where Rp is the portfolio return, Rf the risk-free rate and σp the standard deviation of the portfolio's returns. A higher Sharpe ratio means more return for each unit of risk. It is best used to compare portfolios on the same basis.",
                   ["Sharpe = (Rp − Rf) ÷ σp", "Higher is better", "Compares return per unit of total risk"]),
            _choice("The risk-free rate is 4%. Fund A returned 12% with a standard deviation of 20%. Fund B returned 9% with a standard deviation of 8%.",
                    "Which fund gave the better risk-adjusted return?",
                    [("Fund A, because 12% is higher than 9%", "bad",
                      "Looking only at return ignores risk. Fund A took on 2.5 times as much risk for only a little more return.",
                      _outcome(("Fund A Sharpe ratio ×100", 40), ("Fund B Sharpe ratio ×100", 63), "Fund A: (12 − 4) ÷ 20 = 0.40. Fund B: (9 − 4) ÷ 8 = 0.625.")),
                     ("Fund B, with a Sharpe ratio of 0.625 versus 0.40", "good",
                      "Correct. Fund B earned 5 percentage points above the risk-free rate for 8 points of risk (0.625). Fund A earned 8 above for 20 points of risk (0.40). Fund B was more efficient per unit of risk.",
                      _outcome(("Fund A Sharpe ratio ×100", 40), ("Fund B Sharpe ratio ×100", 63), "Higher means more return for each unit of risk taken.")),
                     ("They cannot be compared because the returns are different", "bad",
                      "Comparing different return and risk levels is exactly what the Sharpe ratio is for.")]),
            _mcq("For the data set 4, 6, 8, 10, 12 (a sample), what is the sample variance?",
                 ["8", "10", "40", "3.16"], 1,
                 "Mean = 8. Sum of squared deviations = 16 + 4 + 0 + 4 + 16 = 40. Sample variance = 40 ÷ (5 − 1) = 10. The standard deviation, about 3.16, is the square root of the variance."),
            _mcq("In a positively skewed distribution, how do the mean and median compare?",
                 ["Mean is greater than the median", "Mean is less than the median", "They are equal", "It depends on the mode only"], 0,
                 "A positive skew has a long right tail of large values that pulls the mean above the median."),
        ], xp=30)

    c4 = _concept(m_id, 4,
        "Probability and the normal distribution",
        "Compute expected value, standardise with a z-score, and use the 68-95-99.7 rule.",
        "Probability turns uncertainty into numbers. Expected value is the probability-weighted average outcome, "
        "and the normal distribution describes how many real-world returns spread out around their average.",
        "A project has a 50% chance of a ₹40,000 profit and a 50% chance of a ₹10,000 loss. Its expected profit is ₹15,000.",
        ["Expected value = Σ (probability × outcome).",
         "About 68%, 95% and 99.7% of normal values lie within 1, 2 and 3 standard deviations.",
         "z = (x − mean) ÷ standard deviation.",
         "Compare projects by expected value, but also consider the spread of outcomes."],
        ["Picking the option that wins most often instead of the one with the higher expected value.",
         "Forgetting that probabilities must sum to 1.",
         "Using a z-score without checking the distribution is roughly normal."],
        [
            _intro("Betting on numbers", "Would you take a bet that wins ₹40,000 half the time and loses ₹10,000 the other half? Expected value gives you a clear answer before you decide."),
            _teach("Expected value and the normal distribution",
                   "The expected value of an uncertain outcome is the sum of each outcome multiplied by its probability: E(X) = Σ p × x. The normal distribution is the familiar bell curve, described fully by its mean and standard deviation. For a normal distribution roughly 68% of values fall within one standard deviation of the mean, 95% within two, and 99.7% within three. A z-score standardises a value: z = (x − mean) ÷ standard deviation, telling you how many standard deviations it is from the mean.",
                   ["E(X) = Σ p × x", "68% / 95% / 99.7% within 1 / 2 / 3 SD", "z = (x − mean) ÷ SD"]),
            _example("Yearly returns of a fund",
                     "A fund's annual returns are roughly normal with a mean of 10% and a standard deviation of 15%. About 68% of years should fall between −5% and 25% (10% ± 15%), and about 95% between −20% and 40% (10% ± 30%). A year with a return of 25% is exactly one standard deviation above the mean, so its z-score is (25 − 10) ÷ 15 = 1.0.",
                     "The 68-95-99.7 rule gives quick ranges, and the z-score tells you how unusual a value is."),
            _flash("What is the z-score formula?", "z = (x − mean) ÷ standard deviation."),
            _choice("Two projects are on the table. Project A: 50% chance of a ₹40,000 profit and 50% chance of a ₹10,000 loss. Project B: 70% chance of a ₹20,000 profit and 30% chance of a ₹10,000 loss.",
                    "Which project has the higher expected profit?",
                    [("Project B, because it makes money more often (70% versus 50%)", "bad",
                      "How often you win is only half the story. Expected value also depends on how much you win and lose.",
                      _outcome(("Project B expected profit", 11000), ("Project A expected profit", 15000), "B: 0.7 × 20,000 − 0.3 × 10,000 = ₹11,000. A: 0.5 × 40,000 − 0.5 × 10,000 = ₹15,000.")),
                     ("Project A, with an expected profit of ₹15,000 versus ₹11,000", "good",
                      "Correct. A: 0.5 × 40,000 + 0.5 × (−10,000) = ₹15,000. B: 0.7 × 20,000 + 0.3 × (−10,000) = ₹11,000. Size of outcomes matters as well as probability.",
                      _outcome(("Project B expected profit", 11000), ("Project A expected profit", 15000), "A wins less often but wins much bigger.")),
                     ("They are equal because both have a 50% or better chance of profit", "bad",
                      "Their expected values are different: ₹15,000 for A and ₹11,000 for B.")]),
            _teach("Using z-scores to find probabilities",
                   "Once you have a z-score you can read the probability from a standard normal table or a calculator. For example, a z-score of −1 corresponds to about a 15.9% chance of a value at or below it, and a z-score of about −0.67 corresponds to roughly 25%. A positive z-score above zero means the value is above the mean. For return distributions, the left tail represents losses, which is why risk managers care about it. Remember: the normal distribution is only an approximation, and real market returns often have fatter tails than a normal curve predicts.",
                   ["z = −1: about 15.9% at or below", "z = 0: 50% at or below", "Real returns can have fatter tails than normal"]),
            _choice("A fund's annual return is roughly normal with a mean of 10% and a standard deviation of 15%. A client wants to know how often the fund loses money (a return below 0%).",
                    "What is the best estimate?",
                    [("About 2.5% of years", "bad",
                      "2.5% is the chance of being more than two standard deviations below the mean. A return of 0% is only about 0.67 standard deviations below the mean."),
                     ("About 25% of years: z = (0 − 10) ÷ 15 ≈ −0.67, which corresponds to roughly 25%", "good",
                      "Correct. The z-score for a 0% return is about −0.67, and the probability of a value that far below the mean is roughly 25%. So the fund would be expected to lose money in about one year out of four."),
                     ("About 50% of years, because returns are equally likely to be above or below zero", "bad",
                      "50% would be the chance of being below the mean of 10%, not below zero.")]),
            _mcq("A fund's returns are normal with a mean of 10% and a standard deviation of 15%. What is the z-score of a 25% return?",
                 ["0.5", "1.0", "1.5", "2.0"], 1,
                 "z = (25 − 10) ÷ 15 = 1.0. The return is one standard deviation above the mean."),
            _mcq("For a normal distribution, approximately what percentage of observations fall within two standard deviations of the mean?",
                 ["68%", "95%", "99.7%", "50%"], 1,
                 "About 95%. The rule is 68% within one standard deviation, 95% within two and 99.7% within three."),
        ], xp=30)

    m["concepts"] = [c1, c2, c3, c4]
    ch["modules"] = [m]
    return ch


def build_cfa_course():
    cid = _id()
    return {
        "id": cid, "slug": "cfa-l1-quant-methods", "seed_version": CFA_SEED_VERSION,
        "name": "CFA L1 Prep", "title": "CFA Level I style: Quantitative Methods",
        "certification": "Exam prep",
        "description": "Exam-style practice on time value of money, returns, statistics and the normal distribution. " + DISCLAIMER,
        "color": "#7C3AED", "icon": "Calculator", "order": 2,
        "chapters": [_quant_chapter(cid)],
    }
